package in.safeway.app;
import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.core.Authentication;import org.springframework.transaction.annotation.Transactional;import javax.validation.Valid;import javax.validation.constraints.*;import java.util.*;
@RestController @RequestMapping("/api")
public class ApiController {
 private final UserRepository users;private final ContactRepository contacts;private final LocationRepository locations;private final SosRepository sos;private final PasswordEncoder encoder;private final JwtUtil jwt;private final JourneyRepository journeys;private final BatteryRepository batteries;private final NotificationRepository notifications;
 public ApiController(UserRepository u,ContactRepository c,LocationRepository l,SosRepository s,PasswordEncoder e,JwtUtil j,JourneyRepository jr,BatteryRepository br,NotificationRepository nr){users=u;contacts=c;locations=l;sos=s;encoder=e;jwt=j;journeys=jr;batteries=br;notifications=nr;}
 static class Register { @NotBlank public String name;@Email @NotBlank public String email;@Size(min=8) public String password; }
 static class Login { @Email @NotBlank public String email;@NotBlank public String password; }
 static class ContactInput {@Email @NotBlank public String email;}
 static class LocationInput {@DecimalMin("-90") @DecimalMax("90") public double latitude;@DecimalMin("-180") @DecimalMax("180") public double longitude;public double accuracy;}
 static class SosInput {public String message;}
 private User current(Authentication a){return users.findByEmail(a.getName()).orElseThrow(()->new RuntimeException("User not found"));}
 private Map<String,Object> publicUser(User u){Map<String,Object> m=new LinkedHashMap<String,Object>();m.put("id",u.id);m.put("name",u.name);m.put("email",u.email);return m;}
 private Map<String,Object> authResult(User u){Map<String,Object> m=new LinkedHashMap<String,Object>();m.put("token",jwt.create(u.email));m.put("user",publicUser(u));return m;}
 @PostMapping("/auth/register") public ResponseEntity<?> register(@Valid @RequestBody Register r){if(users.findByEmail(r.email.toLowerCase()).isPresent())return ResponseEntity.badRequest().body(error("Email already registered"));User u=new User(r.name,r.email.toLowerCase(),encoder.encode(r.password));users.save(u);return ResponseEntity.ok(authResult(u));}
 @PostMapping("/auth/login") public ResponseEntity<?> login(@Valid @RequestBody Login r){Optional<User> u=users.findByEmail(r.email.toLowerCase());if(!u.isPresent()||!encoder.matches(r.password,u.get().password))return ResponseEntity.status(401).body(error("Invalid email or password"));return ResponseEntity.ok(authResult(u.get()));}
 @GetMapping("/auth/me") public Object me(Authentication a){return publicUser(current(a));}
 @PostMapping("/contacts/invite") @Transactional public Object invite(Authentication a,@Valid @RequestBody ContactInput in){User owner=current(a);User target=users.findByEmail(in.email.toLowerCase()).orElseThrow(()->new RuntimeException("No registered user with that email"));if(owner.id.equals(target.id))throw new RuntimeException("You cannot add yourself");for(TrustedContact c:contacts.findByOwnerId(owner.id))if(c.contact.id.equals(target.id))throw new RuntimeException("Invitation already exists");TrustedContact c=contacts.save(new TrustedContact(owner,target));Map<String,Object> m=new LinkedHashMap<String,Object>();m.put("id",c.id);m.put("status",c.status);m.put("contact",publicUser(target));return m;}
 @GetMapping("/contacts") public Object contactList(Authentication a){User u=current(a);List<Map<String,Object>> out=new ArrayList<Map<String,Object>>();for(TrustedContact c:contacts.findByOwnerId(u.id)){Map<String,Object> m=new LinkedHashMap<String,Object>();m.put("id",c.id);m.put("status",c.status);m.put("user",publicUser(c.contact));m.put("direction","OUTGOING");out.add(m);}for(TrustedContact c:contacts.findByContactId(u.id)){Map<String,Object> m=new LinkedHashMap<String,Object>();m.put("id",c.id);m.put("status",c.status);m.put("user",publicUser(c.owner));m.put("direction","INCOMING");out.add(m);}return out;}
 @PostMapping("/contacts/{id}/accept") public Object accept(Authentication a,@PathVariable Long id){User u=current(a);TrustedContact c=contacts.findById(id).orElseThrow(()->new RuntimeException("Invitation not found"));if(!c.contact.id.equals(u.id))throw new RuntimeException("Not your invitation");c.status="ACCEPTED";contacts.save(c);return Collections.singletonMap("status",c.status);}
 @DeleteMapping("/contacts/{id}") public Object remove(Authentication a,@PathVariable Long id){User u=current(a);TrustedContact c=contacts.findById(id).orElseThrow(()->new RuntimeException("Contact not found"));if(!c.owner.id.equals(u.id)&&!c.contact.id.equals(u.id))throw new RuntimeException("Not allowed");contacts.delete(c);return Collections.singletonMap("removed",true);}
 @PostMapping("/locations") public Object saveLocation(Authentication a,@Valid @RequestBody LocationInput in){User u=current(a);LocationPoint p=locations.save(new LocationPoint(u,in.latitude,in.longitude,in.accuracy));Map<String,Object> m=new LinkedHashMap<String,Object>();m.put("id",p.id);m.put("recordedAt",p.recordedAt.toString());return m;}
 @GetMapping("/users/{id}/location/latest") public Object latest(Authentication a,@PathVariable Long id){User viewer=current(a);boolean allowed=viewer.id.equals(id);for(TrustedContact c:contacts.findByOwnerId(id))if(c.contact.id.equals(viewer.id)&&"ACCEPTED".equals(c.status))allowed=true;if(!allowed)throw new RuntimeException("Location access requires an accepted trusted-contact connection");LocationPoint p=locations.findTopByUserIdOrderByRecordedAtDesc(id).orElseThrow(()->new RuntimeException("No location has been shared yet"));Map<String,Object> m=new LinkedHashMap<String,Object>();m.put("user",publicUser(p.user));m.put("latitude",p.latitude);m.put("longitude",p.longitude);m.put("accuracy",p.accuracy);m.put("recordedAt",p.recordedAt.toString());return m;}
 @PostMapping("/sos") public Object createSos(Authentication a,@RequestBody SosInput in){User u=current(a);SosAlert s=sos.save(new SosAlert(u,in.message==null?"Emergency assistance requested":in.message));notifyAccepted(u,"SOS","SOS alert from "+u.name+". Open the app to view the last successfully shared location.");Map<String,Object> m=new LinkedHashMap<String,Object>();m.put("id",s.id);m.put("status",s.status);m.put("createdAt",s.createdAt.toString());m.put("lastLocationAvailable",locations.findTopByUserIdOrderByRecordedAtDesc(u.id).isPresent());m.put("note","SOS and in-app notifications saved. Contacts can view your last successfully uploaded location. No SMS or police dispatch is sent.");return m;}
 @GetMapping("/sos/history") public Object sosHistory(Authentication a){return sos.findByUserIdOrderByCreatedAtDesc(current(a).id);}
 private Map<String,String> error(String s){return Collections.singletonMap("error",s);}

 static class BatteryInput { @Min(0) @Max(100) public Integer level; public Boolean charging; }
 static class JourneyInput { @NotBlank public String destination; @NotNull public String expectedArrival; }
 static class CheckInInput { public String note; }
 private boolean accepted(Long ownerId,Long contactId){for(TrustedContact c:contacts.findByOwnerId(ownerId))if(c.contact.id.equals(contactId)&&"ACCEPTED".equals(c.status))return true;return false;}
 private void notifyAccepted(User owner,String type,String message){for(TrustedContact c:contacts.findByOwnerId(owner.id))if("ACCEPTED".equals(c.status))notifications.save(new SafetyNotification(c.contact,owner,type,message));}
 @PostMapping("/battery") public Object battery(Authentication a,@RequestBody BatteryInput in){if(in.level==null||in.level<0||in.level>100)throw new RuntimeException("Battery level must be between 0 and 100");User u=current(a);BatteryReport b=batteries.save(new BatteryReport(u,in.level,Boolean.TRUE.equals(in.charging)));if(in.level<=20)notifyAccepted(u,"LOW_BATTERY","Low battery: "+in.level+"%. Last successfully shared location is available if one exists.");return Collections.singletonMap("reportedAt",b.reportedAt.toString());}
 @GetMapping("/battery/latest/{userId}") public Object batteryLatest(Authentication a,@PathVariable Long userId){User viewer=current(a);if(!viewer.id.equals(userId)&&!accepted(userId,viewer.id))throw new RuntimeException("Accepted trusted contact required");return batteries.findTopByUserIdOrderByReportedAtDesc(userId).orElseThrow(()->new RuntimeException("No battery report available"));}
 @PostMapping("/journeys") public Object createJourney(Authentication a,@Valid @RequestBody JourneyInput in){User u=current(a);Journey j=journeys.save(new Journey(u,in.destination,java.time.LocalDateTime.parse(in.expectedArrival)));notifyAccepted(u,"JOURNEY_STARTED","Safe journey started: "+j.destination+". Expected arrival: "+j.expectedArrival);return j;}
 @GetMapping("/journeys") public Object myJourneys(Authentication a){return journeys.findByUserIdOrderByCreatedAtDesc(current(a).id);}
 @PostMapping("/journeys/{id}/check-in") public Object checkIn(Authentication a,@PathVariable Long id,@RequestBody CheckInInput in){User u=current(a);Journey j=journeys.findById(id).orElseThrow(()->new RuntimeException("Journey not found"));if(!j.user.id.equals(u.id))throw new RuntimeException("Not your journey");if(!"ACTIVE".equals(j.status))throw new RuntimeException("Journey is not active");j.lastCheckIn=in.note==null?"Manual check-in":in.note;j.updatedAt=java.time.LocalDateTime.now();journeys.save(j);notifyAccepted(u,"JOURNEY_CHECK_IN","Check-in received for "+j.destination);return j;}
 @PostMapping("/journeys/{id}/arrive") public Object arrive(Authentication a,@PathVariable Long id){User u=current(a);Journey j=journeys.findById(id).orElseThrow(()->new RuntimeException("Journey not found"));if(!j.user.id.equals(u.id))throw new RuntimeException("Not your journey");j.status="COMPLETED";j.updatedAt=java.time.LocalDateTime.now();journeys.save(j);notifyAccepted(u,"JOURNEY_COMPLETED","Journey completed: "+j.destination);return j;}
 @PostMapping("/journeys/{id}/cancel") public Object cancelJourney(Authentication a,@PathVariable Long id){User u=current(a);Journey j=journeys.findById(id).orElseThrow(()->new RuntimeException("Journey not found"));if(!j.user.id.equals(u.id))throw new RuntimeException("Not your journey");j.status="CANCELLED";j.updatedAt=java.time.LocalDateTime.now();journeys.save(j);notifyAccepted(u,"JOURNEY_CANCELLED","Journey cancelled: "+j.destination);return j;}
 @GetMapping("/notifications") public Object myNotifications(Authentication a){return notifications.findByRecipientIdOrderByCreatedAtDesc(current(a).id);}
 @ExceptionHandler(Exception.class) public ResponseEntity<?> handle(Exception e){return ResponseEntity.badRequest().body(error(e.getMessage()==null?"Request failed":e.getMessage()));}
}
